    "/us/en/acute-care/products/vocera-analytics": { "template": "product-detail", "metadata": { "title": "Vocera Analytics", "pageTitle": null, "description": "Get the consolidated, holistic insight you need to more effectively optimize communication workflows, reduce clinician interruptions, identify root causes of sentinel events, and achieve clinical imperatives for improving patient care. \r\n\r\nVocera Analytics, a core feature of the Vocera platform, is a monitoring and diagnostic tool that provides visibility to all traffic that goes through the Vocera platform. It can help you optimize usage and adoption of Vocera technology, demonstrate ROI, and proactively identify infrastructure issues. ", "image": "/content/dam/stryker/acute-care/products/vocera-ease/images/vocera-ease-analytics_three-devices.png", "imageAlt": "Vocera Ease Analytics device screen samples", "tags": ["stryker:content-type/product", "stryker:content-type/hcp_content", "stryker:business-unit/acute-care"], "originallyPublished": null, "lastPublished": "2024-02-20T19:36:37.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "2761", "afterSubmitAction": "showMessage", "message": "Thank you for filling out the form! A Stryker representative will be in contact with you shortly.", "useProduction": true }], "tabs": [], "cardLists": [{ "component": "customizable_copy_co", "title": "Related products", "items": [{ "path": "/us/en/acute-care/products/vocera-engage", "resolved": false }, { "path": "/us/en/acute-care/products/vocera-edge", "resolved": false }, { "path": "/us/en/acute-care/products/vocera-smartbadge", "resolved": false }, { "path": "/us/en/acute-care/products/vocera-minibadge", "resolved": false }] }], "missingAlt": [] },
    "/us/en/communications/products/Fortress-wall-system": { "template": "product-detail", "metadata": { "title": "Fortress Wall System", "pageTitle": "Fortress stainless steel modular wall system", "description": "Discover the benefits of the stainless steel modular wall system designed for hospitals and ambulatory surgery centers. Fast, flexible, and future-proof.\r\n\r\n", "image": "/content/dam/stryker/communications/products/fortress-walls/images/OR-Thumb.png", "imageAlt": "OR-Thumb", "tags": ["stryker:content-type/product", "stryker:business-unit/communications", "stryker:content-type/hcp_content", "stryker:portfolio/medical-and-surgical-equipment", "stryker:capability/infrastructure-and-room-design", "stryker:specialty/or-walls"], "originallyPublished": "2024-07-17T18:00:56.000Z", "lastPublished": "2026-06-29T19:13:06.000Z", "contentID": "100904738 Rev A" }, "anchors": [], "disclaimer": "<p>*Based on publicly available information as of January 2024</p>", "forms": [{ "formId": "2951", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [{ "component": "customizable", "title": "Related products", "items": [{ "path": "/us/en/communications/systems/-isuite-experience", "resolved": true, "title": "The iSuite Experience", "description": "You are team-oriented. We are too. Together we share a common goal of providing exceptional patient care. This begins with the iSuite - your customized, efficient, seamlessly integrated operating room. To create your iSuite, our team will guide you through the entire process, one we\u2019ve successfully completed thousands of times. This includes designing and planning your room, providing world-class ", "image": "/content/dam/stryker/communications/systems/isuite-experience/2022-assets/images/thumbnail.png", "alt": "Operating room, Stryker Operating Room, iSuite, Operating Theater, Integrated operating room" }] }], "missingAlt": [] },
    "/us/en/communications/products/accend-surgical-light": { "template": "product-detail", "metadata": { "title": "Accend Surgical Light", "pageTitle": "Accend Surgical Light", "description": "Accend Surgical Light provides you, our customer, exactly what you need. With our design expertise, templated rooms, and standardized configurations we've taken the guesswork out of your decision making process. We have created these solutions so you can keep the patient at the forefront of your mind. ", "image": "/content/dam/stryker/communications/products/accend-surgical-lights/images/Thumb.png", "imageAlt": "OR light, Surgical Light, ASC surigcal light, OR light handle, ASC, Ambulatory Surgery center", "tags": ["stryker:content-type/product", "stryker:capability/asc", "stryker:portfolio/medical-and-surgical-equipment", "stryker:business-unit/communications", "stryker:content-type/hcp_content", "stryker:capability/infrastructure-and-room-design", "stryker:specialty/lighting", "stryker:product/communications/accend-surgical-light"], "originallyPublished": "2023-02-06T19:12:16.000Z", "lastPublished": "2026-06-29T19:12:16.000Z", "contentID": null }, "anchors": [], "disclaimer": "<p>1000904167 REV A</p>", "forms": [{ "formId": "2951", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
