    "/us/en/communications/products/connected-or-ip": { "template": "product-detail", "metadata": { "title": "Connected OR IP BRAVoE", "pageTitle": "Connected OR IP BRAVoE", "description": "The Connected OR IP BRAVoE integration platform Stryker\u2019s Connected OR integration platform optimizes the surgical environment by leveraging intelligence and automation with efficiency & safety in mind, while enhancing the experience for the patient and surgical team.", "image": "/content/dam/stryker/communications/products/connectedor-ip/images/IP-BRAVoE-thumbnail.jpg", "imageAlt": "Connected OR IP", "tags": ["stryker:content-type/product", "stryker:product/communications", "stryker:specialty/OR-integration", "stryker:portfolio/medical-and-surgical-equipment", "stryker:product/communications/connected-or-ip", "stryker:capability/integration-and-connectivity", "stryker:business-unit/communications", "stryker:specialty/or", "stryker:content-type/hcp_content", "stryker:capability/infrastructure-and-room-design"], "originallyPublished": "2023-02-06T17:09:46.000Z", "lastPublished": "2026-06-29T19:08:06.000Z", "contentID": "ENDO-GSNPS-SYK-1839050" }, "anchors": [], "disclaimer": "<p>Resources:&nbsp;</p>\r\n<ol>\r\n<li><span>DHD14285</span></li>\r\n</ol>\r\n<div>Manufacturer part number: ECO092847</div>", "forms": [{ "formId": "2951", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": ["/content/dam/stryker/communications/products/connectedor-ip/images/SYKC.Stryker.com.Products.COR-IP_R2-ASSETSPic1.png", "/content/dam/stryker/communications/products/connectedor-ip/images/SYKC.Stryker.com.Products.COR-IP_R2-ASSETSPic2.png", "/content/dam/stryker/communications/products/connectedor-ip/images/SYKC.Stryker.com.Products.COR-IP_R2-ASSETSPic3.png"] },
