    "/us/en/communications/products/hospital-status": { "template": "product-detail", "metadata": { "title": "Hospital Status", "pageTitle": "Hospital Status", "description": "Designed to improve hospital workflow and provide visibility into any area of the hospital by streaming live video feeds to your desktop or tablet. Hospital Status allows you to easily group and manage all your video feeds in one place. ", "image": "/content/dam/stryker/communications/products/hospital-status/images/SYKC.Stryker.com.Products.HospitalStatus_R2-ASSETSThumbnail.png", "imageAlt": "Hospital status", "tags": ["stryker:content-type/product", "stryker:portfolio/medical-and-surgical-equipment", "stryker:capability/integration-and-connectivity", "stryker:specialty/hospital-enterprise-software", "stryker:business-unit/communications", "stryker:specialty/camera-systems", "stryker:specialty/or", "stryker:content-type/hcp_content", "stryker:capability/infrastructure-and-room-design"], "originallyPublished": "2023-02-06T19:07:20.000Z", "lastPublished": "2026-06-29T19:07:20.000Z", "contentID": "Lit number: 1000903444 Rev A" }, "anchors": [], "disclaimer": "<p>Manufacturer part number:&nbsp;ECO092855</p>", "forms": [{ "formId": "2951", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": ["/content/dam/stryker/communications/products/hospital-status/images/SYKC.Stryker.com.Products.HospitalStatus_R2-ASSETSPic1.png"] },
