    "/us/en/communications/products/room-cameras": { "template": "product-detail", "metadata": { "title": "Room cameras", "pageTitle": null, "description": "We offer a ceiling or wall-mounted HD PTZ camera that is ideal for broadcasting high definition video signals from your operating room, for room to room conferencing or offsite video broadcasts.\r\n", "image": "/content/dam/stryker/communications/products/cameras/images/Thumb-PTZ.jpg", "imageAlt": null, "tags": ["stryker:content-type/product", "stryker:capability/integration-and-connectivity", "stryker:business-unit/communications", "stryker:services/procare/communications/or-integration-and-connectivity", "stryker:specialty/camera-systems", "stryker:portfolio/medical-and-surgical-equipment", "stryker:product/communications/room-cameras", "stryker:content-type/hcp_content"], "originallyPublished": "2023-02-06T17:57:34.000Z", "lastPublished": "2026-06-29T17:57:34.000Z", "contentID": "Literature Number: 1000902497, Rev. A" }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "2951", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
