    "/us/en/communications/products/wall-control": { "template": "product-detail", "metadata": { "title": "Wall Control", "pageTitle": "Wall Control", "description": "Focus on your patients, not your lights with Stryker\u2019s Wall Control for F Generation surgical lights. Control brightness, color temperature, spot size and in-light cameras for up to four surgical lights in your OR. The user interface is specifically designed to be intuitive and easy to use for all staff.", "image": "/content/dam/stryker/communications/products/wall-control/images/SYKC.Stryker.com.Products.HospitalStatus_R2-ASSETSThumbnail.jpg", "imageAlt": "Wall control", "tags": ["stryker:content-type/product", "stryker:portfolio/medical-and-surgical-equipment", "stryker:capability/integration-and-connectivity", "stryker:business-unit/communications", "stryker:specialty/or", "stryker:content-type/hcp_content", "stryker:capability/infrastructure-and-room-design"], "originallyPublished": "2023-02-06T19:08:44.000Z", "lastPublished": "2026-06-29T19:08:44.000Z", "contentID": "1000902250 Rev D" }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "2951", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": ["/content/dam/stryker/communications/products/wall-control/images/SYKC.Stryker.com.Products.HospitalStatus_R2-ASSETSPic2.jpg", "/content/dam/stryker/communications/products/wall-control/images/SYKC.Stryker.com.Products.HospitalStatus_R2-ASSETSPic1.jpg"] },
    "/us/en/communications/products/wall-control/sirca-exam-light": { "template": "product-detail", "metadata": { "title": "Sirca Exam Light", "pageTitle": "Sirca", "description": "Designed to provide bright illumination for intensive critical care environments, the Sirca Exam Light provides trustworthy quality with simplicity. With multiple mounting options and levels of control, experience Stryker\u2019s new exam light.", "image": "/content/dam/stryker/communications/products/sirca-exam-light/images/Thumbnail.png", "imageAlt": "Sirca Exam Light", "tags": ["stryker:content-type/product", "stryker:product/communications", "stryker:portfolio/medical-and-surgical-equipment", "stryker:business-unit/communications", "stryker:product/communications/sirca-exam-light", "stryker:content-type/hcp_content", "stryker:capability/infrastructure-and-room-design", "stryker:specialty/infrastructure-and-room-design", "stryker:specialty/lighting"], "originallyPublished": "2023-02-06T19:09:30.000Z", "lastPublished": "2026-06-29T19:09:30.000Z", "contentID": "Part No. 1000904450" }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "2951", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
