    "/us/en/endoscopy/products/5-0-mm-laparoscopic-instruments": { "template": "product-detail", "metadata": { "title": "5.0 mm laparoscopic instruments", "pageTitle": null, "description": "Our high quality, stainless steel instrumentation line offers a variety of handle and insert styles for grasping, dissecting, suturing and cutting capabilities.\r\n", "image": "/content/dam/stryker/endoscopy/products/5-0mmlaparoscopicinstruments/images/5.0LaparoscopicIntruments-Thumb.jpg", "imageAlt": null, "tags": ["stryker:business-unit/endoscopy", "stryker:product/endoscopy/5-0mm-laparoscopic-instruments", "stryker:content-type/product", "stryker:portfolio/medical-and-surgical-equipment", "stryker:capability/surgical-visualization", "stryker:specialty/laparoscopy", "stryker:content-type/hcp_content"], "originallyPublished": "2023-02-06T18:26:15.000Z", "lastPublished": "2026-06-30T18:26:15.000Z", "contentID": "Literature Number: 1000902490, Rev. A" }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "4047", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
