    "/us/en/endoscopy/products/ahto-pump": { "template": "product-detail", "metadata": { "title": "AHTO pump", "pageTitle": null, "description": "Cordless irrigation console that is hassle-free* and extremely reliable for any general surgery case. <br>\r\n<br>\r\n<br>\r\n<i>*no need to prime</i>", "image": "/content/dam/stryker/endoscopy/products/ahtopump/images/AHTO-Thumb.jpg", "imageAlt": null, "tags": ["stryker:capability/surgical-visualization", "stryker:specialty/laparoscopy", "stryker:content-type/product", "stryker:portfolio/medical-and-surgical-equipment", "stryker:services/procare/endoscopy/surgical-visualization/laparoscopy", "stryker:business-unit/endoscopy", "stryker:product/endoscopy/ahto-pump", "stryker:content-type/hcp_content"], "originallyPublished": "2023-02-06T18:27:22.000Z", "lastPublished": "2026-06-30T18:27:22.000Z", "contentID": "Literature Number: 1000902490, Rev. A ( * no need to prime)" }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "4047", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/endoscopy/products/aim-4k-autoclavable-camera": { "template": "product-detail", "metadata": { "title": "AIM 4K Autoclavable Camera", "pageTitle": "AIM 4K Autoclavable Camera", "description": "The Advanced Imaging Modality (AIM) 4K Autoclavable Camera Head offers brilliant 4K resolution for crystal-clear images, advanced imaging modalities and is autoclavable(1) to fit the particular needs of your facility.\r\n<br><br>\r\n1. Data on File: P46385, Video Devices Processing Guide", "image": "/content/dam/stryker/endoscopy/products/aim4k-autoclavable-camera/images/thumb-4kautoclave.png", "imageAlt": "Advanced Imaging Modalities 4k surgical autoclavable camera head", "tags": ["stryker:capability/surgical-visualization", "stryker:content-type/product", "stryker:business-unit/endoscopy", "stryker:specialty/camera-systems", "stryker:portfolio/medical-and-surgical-equipment", "stryker:content-type/hcp_content"], "originallyPublished": "2023-02-06T18:07:28.000Z", "lastPublished": "2026-06-30T18:07:28.000Z", "contentID": null }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "4047", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [{ "component": "customizable", "title": "Related products", "items": [{ "path": "/us/en/endoscopy/systems/1688-aim-platform", "resolved": true, "title": "1688 Advanced Imaging Modalities (AIM) 4K Platform", "description": "laparoscopic tower, endoscopic tower, stryker 1688", "image": "/content/dam/stryker/endoscopy/systems/1688/main-page/images/1688-AssetsThumbnail.jpg", "alt": null }, { "path": "/us/en/endoscopy/products/4k-32--surgical-monitor-", "resolved": true, "title": "4K 32\u201D OLED monitor", "description": "Our 32\u201D 4K Organic Light-Emitting Diode (OLED) Surgical Display is designed to enhance the visual experience in the operating room.* At just 14 pounds, this display provides over one billion colors and precise viewing at a variety of angles. <br><br> *Compared to other surgical displays on the market.", "image": "/content/dam/stryker/endoscopy/products/4k-oled-monitor/images/thumb.png", "alt": "4K 32 inch OLED surgical monitor showcasing anatomy" }, { "path": "/us/en/endoscopy/products/l-11-light-source-and-auto-light-technology0", "resolved": true, "title": "L-11 Light Source and Auto-light Technology", "description": "The proprietary autolight technology which is designed to automatically provide consistent lighting based on anatomy, enables surgeons to focus on the procedure at hand and nothing else.", "image": "/content/dam/stryker/endoscopy/products/l11lightsource/images/HeroL11-thumb.jpg", "alt": null }, { "path": "/us/en/endoscopy/products/1688-camera-head-with-4k-image-resolution0", "resolved": true, "title": "1688 Camera Head with 4K Image Resolution", "description": "The 1688 camera head offers brilliant 4K resolution for crystal-clear images and improved visualization during surgery. *<br> <br> <br> <br> *As compared to previous generations and/or non 4K systems.", "image": "/content/dam/stryker/endoscopy/products/1688camerasystem/images/Hero1688Head - Hero_2.jpg", "alt": null }] }], "missingAlt": [] },
    "/us/en/endoscopy/products/arthroscopic-instrument-trays": { "template": "product-detail", "metadata": { "title": "Arthroscopic instrument trays", "pageTitle": null, "description": "Sterilization trays are plastic and/or metal containers used to hold and protect arthroscopic surgical devices during the sterilization process. They consist of an interlocking tray and lid, which are both perforated to allow the passage of sterilizing agent from outside the tray to the devices placed inside.\r\n", "image": "/content/dam/stryker/endoscopy/products/sterilizationtrays/images/Thumb-SterilizationTray.jpg", "imageAlt": null, "tags": ["stryker:capability/surgical-visualization", "stryker:content-type/product", "stryker:business-unit/endoscopy", "stryker:portfolio/medical-and-surgical-equipment", "stryker:content-type/hcp_content"], "originallyPublished": "2023-02-06T14:48:43.000Z", "lastPublished": "2026-07-01T14:48:43.000Z", "contentID": "Literature Number: 1000902488, Rev. A" }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "4047", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
