    "/us/en/foot-and-ankle/products/futura-csi": { "template": "product-detail", "metadata": { "title": "Futura CSI", "pageTitle": "Futura CSI", "description": "The Futura CSI Implant is a one-piece device made of Titanium intended to treat hyperpronated foot and stabilize the subtalar joint.", "image": "/content/dam/stryker/foot-and-ankle/products/all-products/2024-brandrefresh/product-thumbnails/Thumb-FuturaCSI.png", "imageAlt": "Futura Conical Subtalar Implant CSI", "tags": ["stryker:capability/foot-and-ankle", "stryker:procedure/foot-and-ankle/-subtalar-arthroeresis/titanium-implants", "stryker:product/foot-and-ankle", "stryker:content-type/product", "stryker:portfolio/orthopaedics", "stryker:content-type/hcp_content"], "originallyPublished": "2026-03-04T13:03:35.000Z", "lastPublished": "2026-03-06T22:10:28.000Z", "contentID": "FA-FCSI-SYK-2572450_REV-0_en_us" }, "anchors": [{ "id": "about", "title": "about", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "specification", "title": "specification", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "specification", "title": "Specification", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "contact", "title": "contact", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }], "disclaimer": null, "forms": [{ "formId": "3079", "afterSubmitAction": "showMessage", "message": "Thank you!", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
