    "/us/en/neurovascular/products/axs-offset": { "template": "product-detail", "metadata": { "title": "AXS Offset", "pageTitle": "AXS Offset", "description": "The unique design of the AXS Offset Delivery Assist Catheter reduces the\r\nspace between the guidewire and intermediate catheter, for\r\nadvancement past neurovascular arterial challenges.", "image": "/content/dam/stryker/neurovascular/products/axs-offset/AXS Offset_NoRing.png", "imageAlt": "AXS Offset", "tags": ["stryker:content-type/product", "stryker:specialty/access", "stryker:product/neurovascular/axs-offset", "stryker:portfolio/neurotechnology", "stryker:business-unit/neurovascular", "stryker:capability/neurovascular", "stryker:content-type/hcp_content", "stryker:specialty/hemorrhagic-stroke-hem"], "originallyPublished": "2023-02-06T16:51:11.000Z", "lastPublished": "2025-01-08T16:51:11.000Z", "contentID": "AP001666 v2.0" }, "anchors": [], "disclaimer": null, "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
