    "/us/en/orthopaedic-instruments/products/steri-shield-8": { "template": "product-detail", "metadata": { "title": "Steri-Shield 8", "pageTitle": null, "description": "Just as no two patients are the same, no two surgeons are the same. That\u2019s why we created Steri-Shield 8: a lighter*, quieter* Stryker helmet with three points of contact for a customizable fit.", "image": "/content/dam/stryker/orthopaedic-instruments/products/steri-shield-8/images/Alyssa half helmet.png", "imageAlt": "Alyssa half helmet", "tags": ["stryker:product/orthopaedic_instruments/steri-shield-8", "stryker:content-type/product", "stryker:capability/personal-protection-equipment", "stryker:content-type/hcp_content", "stryker:business-unit/orthopaedic_instruments", "stryker:portfolio/medical-and-surgical-equipment"], "originallyPublished": "2025-03-03T14:22:32.000Z", "lastPublished": "2025-07-17T18:24:27.000Z", "contentID": "OI-GSNPS-SYK-1629566_REV-0" }, "anchors": [{ "id": "contact", "title": "Contact us", "hidden": false, "type": "section-title", "area": "customizablearea_parsys" }], "disclaimer": null, "forms": [{ "formId": "3421", "afterSubmitAction": "showMessage", "message": "Thank you!", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
