    "/us/en/smart-care/products/sync-badge": { "template": "product-detail", "metadata": { "title": "Sync Badge", "pageTitle": "Sync Badge | Hands-free hospital communication ", "description": "Inspired by nurses and designed for fast, reliable collaboration and enhanced workflow efficiency", "image": "/content/dam/stryker/acute-care/products/sync-badge/images/sync-badge-thumbnail_1200x680.jpg", "imageAlt": "Sync Badge", "tags": ["stryker:content-type/product", "stryker:portfolio/medical-and-surgical-equipment", "stryker:capability/smart-hospital", "stryker:business-unit/smart-care", "stryker:specialty/clinical-communication", "stryker:product/smart-care/sync-badge", "stryker:content-type/hcp_content", "stryker:custom/smart-care/care-space/smarted", "stryker:custom/smart-care/care-space/smartroom", "stryker:custom/smart-care/care-space/smartor", "stryker:custom/smart-care/product-type/clinical-communication"], "originallyPublished": "2025-02-10T15:23:22.000Z", "lastPublished": "2026-08-06T12:58:36.000Z", "contentID": "AC-VBA-SYK-1442578_REV-0_en_us" }, "anchors": [{ "id": "overview", "title": "Overview", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "features", "title": "Features", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "contact", "title": "Contact", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }, { "id": "resources", "title": "Resources", "hidden": true, "type": "section-title", "area": "customizablearea_parsys" }], "disclaimer": "<p>* Minibadge is not available with EMDAN configuration.</p>\r\n<p>** <b>US: </b>Delivery of secondary alarms requires Engage Medical Device Alarm Notification (EMDAN), FDA 510(k)-cleared middleware, part of Stryker\u2019s Vocera Engage middleware. Capabilities are based on your facility\u2019s protocols and technology configuration. <b>Canada: </b>Delivery of secondary alarms requires Engage Medical Device Alarm Notification (EMDAN), part of Stryker\u2019s Vocera Engage middleware. Capabilities are based on your facility\u2019s protocols and technology configuration.</p>", "forms": [{ "formId": "2761", "afterSubmitAction": "showMessage", "message": "Thank you for your interest in our Sync Badge. A Stryker representative will reach out to you shortly.", "useProduction": true }], "tabs": [["Quick, reliable communication", "Workflow efficiency", "Emergency communications"], ["Product Information", "Related products"]], "cardLists": [{ "component": "featuredcontent", "title": null, "items": [{ "path": "/us/en/smart-care/products/vocera-smartbadge", "resolved": true, "title": "Vocera Smartbadge", "description": "Simplify hospital communication and workflow to help improve staff safety and impact on patient care.", "image": "/content/dam/stryker/acute-care/products/vocera-smartbadge/images/vocera-smartbadge_screen_v1.jpg", "alt": "smartbadgescreenoff" }, { "path": "/us/en/smart-care/products/vocera-engage", "resolved": true, "title": "Vocera Engage", "description": "Vocera Engage middleware is the core of Vocera\u2019s communication and workflow intelligence. It provides care teams a more complete picture of a patient\u2019s situation, enabling prompt communication and helping to enhance patient safety.", "image": "/content/dam/stryker/acute-care/products/vocera-engage/images/doctor-on-phone-walking-nurses-in-background.jpg", "alt": "Doctors and nurses walking in a hospital wearing Vocera Badges - hands-free communication devices" }] }], "missingAlt": [] },
