    "/us/en/spine/products/cranial-guidance-software": { "template": "product-detail", "metadata": { "title": "Cranial Guidance Software", "pageTitle": null, "description": null, "image": "/content/dam/stryker/spine/products/q-guidance-system/cranial-software/images/D1BFFE21_021 final approach - top right quad.psd", "imageAlt": "D1BFFE21_021 final approach - top right quad", "tags": ["stryker:specialty/cranial", "stryker:specialty/cranial-navigation", "stryker:content-type/product", "stryker:procedure/spine", "stryker:portfolio/neurotechnology", "stryker:business-unit/spine", "stryker:capability/spine", "stryker:portfolio/orthopaedics", "stryker:specialty/orthopaedic-navigation", "stryker:content-type/hcp_content", "stryker:specialty/neurotechnology", "stryker:capability/navigation"], "originallyPublished": null, "lastPublished": "2023-09-28T18:45:40.000Z", "contentID": "QGS-WB-6_34510" }, "anchors": [], "disclaimer": "<p><b>Associated services<br>\r\n</b></p>\r\n<ul>\r\n<li>Flex Financial \u2013 offers alternative payment structures designed to fit your organization\u2019s needs. This flexibility helps enable you to acquire the technology you need, when you need it.</li>\r\n<li>ProCare \u2013 helps ensure your equipment is consistently ready to perform and helps you optimize your investment via loaners, preventative maintenance solutions and service plans.</li>\r\n</ul>\r\n<p><b>References</b></p>\r\n<ol>\r\n<li>Stryker data on file<br>\r\n</li>\r\n</ol>", "forms": [], "tabs": [], "cardLists": [{ "component": "featuredcontent_copy", "title": "Related products", "items": [{ "path": "/us/en/spine/products/q-guidance-system", "resolved": true, "title": "Q Guidance System", "description": null, "image": "/content/dam/stryker/spine/products/q-guidance-system/images/Q Guidance with SG5 Screw Planning Screen.png", "alt": "spinal navigation and guidance system with pedicle screw planning" }] }], "missingAlt": [] },
