    "/us/en/sustainability/products/ensite-x": { "template": "product-detail", "metadata": { "title": "Reprocessed EP cables", "pageTitle": null, "description": "Reprocessed EP cables are a set of insulated wires, wrapped in a protective coating, with unique connectors on each end. Stryker's Sustainability Solutions reprocessed EP cables are 100% visually inspected and reprocessing cycles are tracked.\r\n\r\n</li><li>Now available: reprocessed Interface cable, reprocessed nGen ablation cable, reprocessed DiamondTemp ablation cable and Orion 78in cable", "image": "/content/dam/stryker/sustainability/images/New cables DiamondnGenOrion.png", "imageAlt": "Ensite X", "tags": ["stryker:content-type/product", "stryker:portfolio/medical-and-surgical-equipment", "stryker:specialty/ep-cables", "stryker:business-unit/sustainability", "stryker:product/sustainability/ensite-x", "stryker:content-type/hcp_content", "stryker:capability/reprocessed-products"], "originallyPublished": "2023-02-06T18:05:00.000Z", "lastPublished": "2026-08-18T20:22:35.000Z", "contentID": "SSS-EPCB-SYK-2417100" }, "anchors": [], "disclaimer": "<p>1 Internal data on file</p>", "forms": [{ "formId": "2736", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
