    "/us/en/sustainability/products/save-simply-sage-prevalon-mats": { "template": "product-detail", "metadata": { "title": "Save Simply Sage Prevalon\xAE MATS ", "pageTitle": null, "description": "We partner with Stryker Sage to offer a blended Prevalon MATS program offering a mixture of both new and reprocessed Prevalon MATS products at one low price. \r\n\r\n<ul>\r\n<li>\u2022 One vendor to order from</li>\r\n<li>\u2022 One hundred percent fill rate</li>\r\n<li>\u2022 Optimized collections</li>\r\n<li>\u2022 Lower total facility cost</li>\r\n<li>\u2022 Divert unnecessary landfill waste</li>\r\n</ul>", "image": "/content/dam/stryker/endoscopy/products/sage-prevalon-mats/images/Sage Prevalon MATS.png", "imageAlt": "Sage Prevalon MATS", "tags": ["stryker:content-type/product", "stryker:portfolio/medical-and-surgical-equipment", "stryker:specialty/save-simply-blended-offerings", "stryker:product/sustainability/prevalon", "stryker:business-unit/sustainability", "stryker:content-type/hcp_content", "stryker:capability/reprocessed-products"], "originallyPublished": "2023-02-06T20:18:59.000Z", "lastPublished": "2026-08-18T20:18:59.000Z", "contentID": "CIS11260" }, "anchors": [], "disclaimer": null, "forms": [{ "formId": "2736", "afterSubmitAction": "showMessage", "message": "Thank you! We have received your request. A Stryker representative will be in contact with you soon.", "useProduction": true }], "tabs": [], "cardLists": [], "missingAlt": [] },
