    "/us/en/trauma-and-extremities/products/allofiber": { "template": "product-detail", "metadata": { "title": "AlloFiber", "pageTitle": null, "description": "AlloFiber is comprised of freeze-dried cortical fibers and can be easily hydrated and mixed with autologous bone, bone marrow aspirate, blood or saline. It is moldable and has a putty-like handling for packing bone voids and gaps.", "image": "/content/dam/stryker/trauma-and-extremeties/products/allofiber/images/AlloFiber-image.jpg", "imageAlt": "image of AlloFiber", "tags": ["stryker:product/trauma-and-extremities/allofiber", "stryker:custom/foot-and-ankle/product-type/biologics", "stryker:content-type/product", "stryker:capability/trauma-and-extremities", "stryker:capability/biologics", "stryker:portfolio/orthopaedics", "stryker:specialty/bone-grafting", "stryker:custom/trauma-and-extremities/biologics/biologics-page-filters/bone-grafting-dbm", "stryker:business-unit/trauma-and-extremities", "stryker:content-type/hcp_content", "stryker:custom/trauma-and-extremities/biologics/bone-grafting/dbm", "stryker:capability/foot-and-ankle", "stryker:business-unit/foot-and-ankle"], "originallyPublished": "2023-02-06T21:25:24.000Z", "lastPublished": "2024-11-08T21:27:33.000Z", "contentID": "AP-015810" }, "anchors": [], "disclaimer": "<ol>\r\n<li>Data on file at MTF<br>\r\n</li>\r\n<li>Gruskin, E., Doll, B. A., Futrell, F. W., Schmitz, J. P., &amp; Hollinger, J. O. (2012). Demineralized bone matrix in bone repair: deliveryreviews, 64(12), 1063\u20131077.</li>\r\n</ol>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/trauma-and-extremities/products/allograft-wedges": { "template": "product-detail", "metadata": { "title": "Foot and Ankle Wedges", "pageTitle": null, "description": "Pre-shaped allograft wedges enable convenient use without the need for intraoperative shaping. ", "image": "/content/dam/stryker/trauma-and-extremeties/products/allograftwedges/images/allograft-wedges.jpg", "imageAlt": null, "tags": ["stryker:custom/trauma-and-extremities/biologics/biologics-page-filters/foot-&-ankle-wedges-f&a-wedges", "stryker:procedure/foot-and-ankle/medial-cuneiform-dorsal-opening-wedge-(cotton)-osteotomy", "stryker:capability/foot-and-ankle", "stryker:capability/biologics", "stryker:product/trauma-and-extremities/allograft-wedges", "stryker:procedure/foot-and-ankle/lateral-column-lengthening-(evans-osteotomy)", "stryker:content-type/hcp_content", "stryker:specialty/foot-and-ankle-wedges", "stryker:custom/foot-and-ankle/product-type/biologics", "stryker:content-type/product", "stryker:capability/trauma-and-extremities", "stryker:custom/trauma-and-extremities/Procedures/Biologics", "stryker:system/trauma-and-extremities/biologics", "stryker:portfolio/orthopaedics", "stryker:procedure/foot-and-ankle/talonavicular-joint-arthrodesis", "stryker:business-unit/trauma-and-extremities", "stryker:custom/trauma-and-extremities/product-type/bone-void-fillers", "stryker:procedure/foot-and-ankle/triple-arthrodesis"], "originallyPublished": null, "lastPublished": "2022-07-06T13:05:29.000Z", "contentID": null }, "anchors": [], "disclaimer": "<p>Processed by: Allosource 6278 S Troy Cir. Centennial, CO 80111 t: 800 557 3587<br>\r\n</p>\r\n<p>CP-AWI-12, 07-2017</p>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
    "/us/en/trauma-and-extremities/products/allomatrix": { "template": "product-detail", "metadata": { "title": "AlloMatrix", "pageTitle": null, "description": "AlloMatrix is a line of demineralized bone matrix (DBM) bone grafting putties containing OsteoSet surgical-grade calcium sulfate.", "image": "/content/dam/stryker/trauma-and-extremeties/products/allomatrix/images/AlloMatrix_AP-015809.jpg", "imageAlt": null, "tags": ["stryker:content-type/product", "stryker:product/trauma-and-extremities/allomatrix", "stryker:capability/biologics", "stryker:portfolio/orthopaedics", "stryker:specialty/bone-grafting", "stryker:business-unit/trauma-and-extremities", "stryker:content-type/hcp_content", "stryker:custom/trauma-and-extremities/biologics/bone-grafting/dbm", "stryker:custom/trauma-and-extremities/biologics/biologics-page-filters/bone-grafting-dbm"], "originallyPublished": null, "lastPublished": "2022-03-10T16:31:34.000Z", "contentID": "AP-015809" }, "anchors": [], "disclaimer": "<p>*All claims based on a critically sized canine proximal humerus defect model. It is unknown how results from the canine model compare with clinical results in humans. Data on file at Stryker</p>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
