    "/us/en/trauma-and-extremities/products/ignite": { "template": "product-detail", "metadata": { "title": "Ignite", "pageTitle": null, "description": "Ignite injectable stimulus combines an injectable cellular scaffold, demineralized bone matrix (DBM), and aspirated bone marrow. The combination provides a minimally invasive graft with osteoconductive, osteoinductive, and osteogenic capacity.", "image": "/content/dam/stryker/trauma-and-extremeties/products/ignite/images/ignite-img2.png", "imageAlt": null, "tags": ["stryker:product/trauma-and-extremities/ignite", "stryker:content-type/product", "stryker:capability/biologics", "stryker:portfolio/orthopaedics", "stryker:specialty/bone-grafting", "stryker:custom/trauma-and-extremities/biologics/biologics-page-filters/bone-grafting-dbm", "stryker:business-unit/trauma-and-extremities", "stryker:content-type/hcp_content", "stryker:custom/trauma-and-extremities/biologics/bone-grafting/dbm", "stryker:capability/trauma-and-extremities"], "originallyPublished": null, "lastPublished": "2022-03-31T18:37:45.000Z", "contentID": "AP-015824" }, "anchors": [], "disclaimer": "<ol>\r\n<li>Scranton PE. Use of bone substitutes in lower extremity reconstructive surgery. Foot and Ankle INT 2002; 23(8): 689-692.<br>\r\n</li>\r\n<li>Wilkins RM, et al. Percutaneous treatment of long bone nonunions: The use of autologous bone marrow and allograft bone matrix. WMT publication, 2002.</li>\r\n</ol>", "forms": [], "tabs": [], "cardLists": [], "missingAlt": [] },
